sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.search = ''; c.stateFilter = ''; c.typeFilter = '';
  c.matches = function(item) {
    if (c.stateFilter && item.state !== c.stateFilter) return false;
    if (c.typeFilter && item.typeVal !== c.typeFilter) return false;
    if (c.search) {
      var q = c.search.toLowerCase();
      return (item.number||'').toLowerCase().indexOf(q) > -1 ||
             (item.type||'').toLowerCase().indexOf(q) > -1;
    }
    return true;
  };
};

sp_widget.css:
.cp-claims { max-width:1120px; margin:0 auto; padding:32px 28px; }
.cp-claims__head { display:flex; justify-content:space-between; align-items:flex-end; gap:16px; margin-bottom:22px; }
.cp-claims__head--mini { align-items:center; margin-bottom:14px; }
.cp-claims__all { color:var(--cp-gold); text-decoration:none; font-weight:750; font-size:14px; }
.cp-claims__filters { display:flex; gap:12px; margin-bottom:22px; flex-wrap:wrap; }
.cp-input { height:42px; padding:0 14px; border:1px solid var(--cp-line); border-radius:10px;
  background:#fff; color:var(--cp-navy); font-size:14px; min-width:160px; }
.cp-input:focus { outline:none; border-color:var(--cp-gold); }
.cp-claims__grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(280px,1fr)); gap:16px; }
.cp-claim { display:block; padding:18px; text-decoration:none; color:inherit; transition:.18s ease; }
.cp-claim:hover { transform:translateY(-2px); border-color:rgba(197,160,101,.55); box-shadow:0 10px 30px rgba(10,37,64,.10); }
.cp-claim__top { display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }
.cp-claim__num { font-weight:850; letter-spacing:.01em; }
.cp-claim__type { color:var(--cp-muted); font-size:13px; text-transform:capitalize; }
.cp-claim__amount { font-size:24px; font-weight:850; margin-top:6px; letter-spacing:-.01em; }
.cp-claim__foot { margin-top:14px; padding-top:12px; border-top:1px solid var(--cp-line); color:var(--cp-muted); font-size:12px; }
.cp-empty { text-align:center; padding:48px 20px; color:var(--cp-muted); grid-column:1/-1; }
.cp-empty p { margin-bottom:14px; }

sp_widget.script:
(function() {
  var STATE = {
    '1': {label:'New',           cls:'cp-badge--new'},
    '2': {label:'Under Review',  cls:'cp-badge--review'},
    '3': {label:'Investigation', cls:'cp-badge--invest'},
    '4': {label:'Approved',      cls:'cp-badge--approved'},
    '5': {label:'Rejected',      cls:'cp-badge--rejected'},
    '7': {label:'Closed',        cls:'cp-badge--closed'}
  };
  data.compact = options.compact === 'true' || options.compact === true;
  var limit = parseInt(options.limit) || 0;

  data.claims = [];
  var gr = new GlideRecord('x_1970973_claim_0_insurance_claims');
  gr.addQuery('customer', gs.getUserID());          // scope to me (defense-in-depth)
  gr.orderByDesc('sys_created_on');
  gr.setLimit(200);                                 // never run unbounded queries
  gr.query();
  while (gr.next()) {
    if (limit && data.claims.length >= limit) break;
    var st = gr.getValue('state') || '1';
    var m = STATE[st] || STATE['1'];
    data.claims.push({
      sys_id:     gr.getUniqueValue(),
      number:     gr.getValue('number'),
      type:       gr.getDisplayValue('claim_type'),
      typeVal:    gr.getValue('claim_type'),
      amount:     gr.getDisplayValue('claim_amount'),
      state:      st,
      stateLabel: m.label,
      stateClass: m.cls,
      created:    gr.getDisplayValue('sys_created_on')
    });
  }
  data.count = data.claims.length;
  data.submitHref = '?id=sc_cat_item&sys_id=18a0bcf7c30147d0b68cd50d05013103';
})();
